/*
 * A142139  Primes congruent to 30 mod 37.
 * https://oeis.org/A142139
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 184, u32 n <= 81, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: primes p such that p % 37 == 30, generated by successive testing
   using is_prime_big.  The function memoises results so calls can be made
   in any order. */
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"

seq_t a(idx_t n)
{
    /* Static cache of found primes (1‑based index). */
    static seq_t *cache   = NULL;   /* array of primes */
    static idx_t  cache_len  = 0;  /* number of stored primes */
    static idx_t  cache_cap  = 0;  /* current capacity of the array */

    /* Current candidate in the progression 30 (mod 37), starting at 67. */
    static seq_t current = 67;

    /* Ensure the cache has at least n primes. */
    if (cache_len < n) {
        /* Expand capacity if necessary. */
        if (cache_cap < n) {
            size_t new_cap = cache_cap ? cache_cap * 2 : 64;
            if (new_cap < (size_t)n) new_cap = n;
            seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
            if (!tmp) abort();   /* out of memory */
            cache = tmp;
            cache_cap = new_cap;
        }

        /* Find primes until we have n of them. */
        while (cache_len < n) {
            if (is_prime_big(current)) {
                cache[cache_len++] = current;
            }
            current += 37;   /* next number ≡ 30 (mod 37) */
        }
    }

    /* Return the requested term (1‑based). */
    return cache[n - 1];
}
